<body>
<div class="container">
  <h1>📝 Todo App</h1>
  <div class="input-row">
    <input type="text" id="todoInput" placeholder="Add a new todo..." autocomplete="off">
    <button class="btn-add" id="addBtn">Add</button>
  </div>
  <div class="filters">
    <button class="filter-btn active" data-filter="all">All</button>
    <button class="filter-btn" data-filter="active">Active</button>
    <button class="filter-btn" data-filter="completed">Completed</button>
  </div>
  <ul class="todo-list" id="todoList"></ul>
</div>

<script>
  // Load todos from localStorage or start empty
  let todos = JSON.parse(localStorage.getItem('todos') || '[]');

  const todoInput = document.getElementById('todoInput');
  const addBtn = document.getElementById('addBtn');
  const todoList = document.getElementById('todoList');

  const filterBtns = document.querySelectorAll('.filter-btn');
  let currentFilter = 'all';

  // Persist to localStorage whenever todos change
  function saveTodos() {
    localStorage.setItem('todos', JSON.stringify(todos));
  }

  // Add a new todo
  function addTodo() {
    const text = todoInput.value.trim();
    if (!text) return;
    todos.unshift({ id: Date.now(), text, completed: false });
    todoInput.value = '';
    saveTodos();
    render();
  }

  // Toggle complete
  function toggleTodo(id) {
    const t = todos.find(x => x.id === id);
    if (t) t.completed = !t.completed;
    saveTodos();
    render();
  }

  // Delete a todo
  function deleteTodo(id) {
    todos = todos.filter(x => x.id !== id);
    saveTodos();
    render();
  }

  // Filter todos
  function getFilteredTodos() {
    switch (currentFilter) {
      case 'active': return todos.filter(t => !t.completed);
      case 'completed': return todos.filter(t => t.completed);
      default: return todos;
    }
  }

  // Render the list
  function render() {
    const items = getFilteredTodos();
    if (items.length === 0) {
      todoList.innerHTML = '<li class="empty-msg">' + (currentFilter === 'active' ? 'No active todos' : currentFilter === 'completed' ? 'No completed todos' : 'No todos yet') + '</li>';
      return;
    }
    todoList.innerHTML = items.map(t =>
      '<li class="todo-item' + (t.completed ? ' completed' : '') + '">' +
        '<span class="todo-text">' + esc(t.text) + '</span>' +
        '<button class="todo-delete" onclick="deleteTodo(' + t.id + ')">&times;</button>' +
      '</li>'
    ).join('');
  }

  // Escape HTML to prevent XSS
  function esc(s) {
    const d = document.createElement('div');
    d.textContent = s;
    return d.innerHTML;
  }

  // Event listeners
  addBtn.addEventListener('click', addTodo);
  todoInput.addEventListener('keydown', e => { if (e.key === 'Enter') addTodo(); });

  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      filterBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentFilter = btn.dataset.filter;
      render();
    });
  });

  // Initial render
  render();
</script>
</body>
